src/app.css:
@import 'tailwindcss/base';
@import 'tailwindcss/components';
@import 'tailwindcss/utilities';

@font-face {
	font-family: 'icons';
	src: url('/font/icons/icons.eot?39963949');
	src:
		url('/font/icons/icons.eot?39963949#iefix') format('embedded-opentype'),
		url('/font/icons/icons.woff2?39963949') format('woff2'),
		url('/font/icons/icons.woff?39963949') format('woff'),
		url('/font/icons/icons.ttf?39963949') format('truetype'),
		url('/font/icons/icons.svg?39963949#icons') format('svg');
	font-weight: normal;
	font-style: normal;
}

[class^='icon-']:before,
[class*=' icon-']:before {
	font-family: 'icons';
	font-style: normal;
	font-weight: normal;
	speak: never;

	display: inline-block;
	text-decoration: inherit;
	width: 1em;
	margin-right: 0.2em;
	text-align: center;
	/* opacity: .8; */

	/* For safety - reset parent styles, that can break glyph codes*/
	font-variant: normal;
	text-transform: none;

	/* fix buttons height, for twitter bootstrap */
	line-height: 1em;

	/* Animation center compensation - margins should be symmetric */
	/* remove if not needed */
	margin-left: 0.2em;

	/* you can be more comfortable with increased icons size */
	/* font-size: 120%; */

	/* Font smoothing. That was taken from TWBS */
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;

	/* Uncomment for 3D effect */
	/* text-shadow: 1px 1px 1px rgba(127, 127, 127, 0.3); */
}

.icon-tap:before {
	content: '\e80d';
}

/* '' */
.icon-close:before {
	content: '\f2d3';
}

/* '' */

